import sys

def find_year(abbreviation):
    suffix = abbreviation[4:]
    year = int(suffix)
    if year < 89:
        return 2000 + year
    else:
        return 1900 + year

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    used_years = set()
    results = []

    for year in range(1989, 3000):
        suffix = str(year)[2:]
        while len(suffix) > 0 and suffix not in used_years:
            used_years.add(suffix)
        if len(suffix) == 0:
            break

    for i in range(1, n + 1):
        abbreviation = input[i]
        result = find_year(abbreviation)
        results.append(str(result))

    print("\n".join(results))

if __name__ == "__main__":
    main()
